/**
 * 1. monitor_module monitor_endpoint 去掉 host port 字段
 * 2. config 修改 prometheus flt模板
 * 3. config 修改 endpoint 导入导出表头
 */
ALTER TABLE monitor_module DROP COLUMN port;

ALTER TABLE monitor_endpoint DROP COLUMN host;
ALTER TABLE monitor_endpoint DROP COLUMN port;


DELETE from sys_config where param_key = "prom_yml_tmpl";
INSERT INTO `sys_config`(`id`, `param_key`, `param_value`, `status`, `remark`) VALUES (NULL, 'prom_yml_tmpl', '{\r\n    \"global\": {\r\n        \"scrape_interval\": \"${scrape_interval}s\",\r\n        \"scrape_timeout\": 	<#if scrape_timeout??> \r\n								\"${scrape_timeout}s\",\r\n						    <#else>\r\n								\"10s\",\r\n							</#if>\r\n        \"evaluation_interval\": \"${scrape_interval}s\"\r\n    },\r\n	\r\n	<#-- alert 配置 -->\r\n	<#if isAlert>\r\n	\"alerting\": {\r\n		\"alertmanagers\": [{\r\n			\"path_prefix\": \"${path_prefix}\",\r\n			\"static_configs\": [{\r\n				\"targets\": [\"${alert_url}\"]\r\n			}]\r\n		}],\r\n		\"alert_relabel_configs\": [{\r\n			\"regex\": \"instance\",\r\n			\"action\": \"labeldrop\"\r\n		}, {\r\n			\"regex\": \"replica\",\r\n			\"action\": \"labeldrop\"\r\n		}]\r\n	},\r\n	\"rule_files\": [\"rule.yml\"],\r\n	</#if>\r\n	\r\n	\r\n	\r\n	<#-- per-datacenter 配置 -->\r\n	<#if !isGlobal>\r\n    \"scrape_configs\": [\r\n		<#list endpointList as endpoint>\r\n			{\r\n				\"job_name\": ${endpoint.id?c},\r\n				\"metrics_path\": <#if endpoint.config.metrics_path?default(\"\")?trim?length gt 1>\r\n									\"${endpoint.config.metrics_path}\",\r\n								<#else>\r\n									\"/metric\",\r\n								</#if>\r\n				\"scrape_interval\": 	<#if endpoint.config.scrape_interval?default(\"\")?trim?length gt 1>\r\n										\"${endpoint.config.scrape_interval}s\",\r\n									<#else>\r\n										\"${scrape_interval}s\",\r\n									</#if>\r\n				\"scrape_timeout\": 	<#if endpoint.config.scrape_timeout?default(\"\")?trim?length gt 1>\r\n										\"${endpoint.config.scrape_timeout}s\",\r\n									<#else>\r\n										<#if scrape_timeout??> \r\n											\"${scrape_timeout}s\",\r\n										<#else>\r\n											\"10s\",\r\n										</#if>\r\n									</#if>\r\n\r\n				\r\n				<#if endpoint.config.basic_auth??&& (endpoint.config.basic_auth?size >0)>\r\n                \"basic_auth\":{\r\n                    \"username\": <#if endpoint.config.basic_auth.username?default(\"\")?trim?length gt 1>\r\n                                \"${endpoint.config.basic_auth.username}\",\r\n                                <#else>\"\",</#if>\r\n                    \"password\": <#if endpoint.config.basic_auth.password?default(\"\")?trim?length gt 1>\r\n                                \"${endpoint.config.basic_auth.password}\"\r\n                                <#else>\"\"</#if>\r\n                    },\r\n				</#if>\r\n				\r\n				\r\n				<#if endpoint.config.bearer_token??> \r\n				\"authorization\":{\r\n						\"type\":\"Bearer\",\r\n						\"credentials\":\"${endpoint.config.bearer_token}\"\r\n					},\r\n				</#if>\r\n\r\n				\r\n				<#-- params 不为空且类型为 http ，添加 params -->\r\n				<#if endpoint.config.params??&& (endpoint.config.params?size >0) && endpoint.module.type == \"http\">\r\n				\"params\":{\r\n					<#list endpoint.config.params?keys as itemKey>\r\n					\"${itemKey}\":[\r\n						<#list endpoint.config.params[itemKey] as pojo>\r\n							\"${pojo}\"\r\n							<#sep>,</#sep>\r\n						</#list>\r\n						]\r\n						<#sep>,</#sep>\r\n					</#list>\r\n				},\r\n				<#elseif endpoint.module.type == \"snmp\">\r\n				<#-- 类型是 snmp ，组织 param 数据 ， 原来params弃用，因为 snmp_exporter 不支持其他参数 -->\r\n			   \"params\":{\r\n					\"target\":[ \"${endpoint.config.host}:${endpoint.config.port?c}\" ],\r\n					\"module\":[ \"${endpoint.module.name}\" ]\r\n				},\r\n				</#if>\r\n				\r\n				\"static_configs\": [{\r\n					\"targets\": [<#if endpoint.module.type == \"http\">\r\n									\"${endpoint.config.host}:${endpoint.config.port?c}\"\r\n								<#else>\r\n									\"127.0.0.1:9116\"\r\n								</#if>\r\n								],\r\n					\"labels\": {\r\n						\"datacenter\": 	<#if endpoint.config.labels??&&endpoint.config.labels.datacenter?default(\"\")?trim?length gt 1>\r\n											\"${endpoint.config.labels.datacenter}\",\r\n										<#else>\r\n											\"${endpoint.dc.name}\",\r\n										</#if>\r\n						\"project\": 		<#if endpoint.config.labels??&&endpoint.config.labels.project?default(\"\")?trim?length gt 1>\r\n											\"${endpoint.config.labels.project}\",\r\n										<#else>\r\n											\"${endpoint.project.name}\", \r\n										</#if>\r\n						\"asset\": 		<#if endpoint.config.labels??&&endpoint.config.labels.asset?default(\"\")?trim?length gt 1>\r\n											\"${endpoint.config.labels.asset}\",\r\n										<#else>\r\n											\"${endpoint.asset.manageIp}\",\r\n										</#if>\r\n						\"module\": 		<#if endpoint.config.labels??&&endpoint.config.labels.module?default(\"\")?trim?length gt 1>\r\n											\"${endpoint.config.labels.module}\"\r\n												<#if endpoint.config.labels??&& (endpoint.config.labels?size >0)>\r\n													,\r\n												</#if>\r\n										<#else>\r\n											\"${endpoint.module.name}\"\r\n												<#if endpoint.config.labels??&& (endpoint.config.labels?size >0)>\r\n													,\r\n												</#if>\r\n										</#if>\r\n										\r\n										<#-- 补充用户自定义 Labels -->\r\n										<#if endpoint.config.labels??&& (endpoint.config.labels?size >0)>\r\n											<#list endpoint.config.labels?keys as key>\r\n												<#if key != \"datacenter\" &&  key != \"module\" &&  key != \"project\" &&  key != \"asset\">\r\n													\"${key}\":\"${endpoint.config.labels[key]}\"<#sep>,</#sep>\r\n												</#if>\r\n											 </#list>\r\n										</#if>\r\n					}\r\n				}],\r\n				\"relabel_configs\": [\r\n					{\r\n						\"regex\": \"instance\",\r\n						\"action\": \"labeldrop\"\r\n					},\r\n					{\r\n						\"source_labels\": [\r\n							\"job\"\r\n						],\r\n						\"regex\": \"(.+)\",\r\n						\"target_label\": \"endpoint\"\r\n					},\r\n					{\r\n						\"regex\": \"job\",\r\n						\"action\": \"labeldrop\"\r\n					}\r\n				],\r\n				\"metric_relabel_configs\": [\r\n					{\r\n						\"regex\": \"instance\",\r\n						\"action\": \"labeldrop\"\r\n					}\r\n				]\r\n			}\r\n			<#sep>,</#sep>\r\n		</#list>\r\n    ]\r\n	<#else>\r\n	<#-- global 配置 -->\r\n	\"scrape_configs\": [\r\n		<#list jobList as jobPojo>\r\n			{\r\n			   \"job_name\": \"${jobPojo.job_name}\",\r\n				<#if jobPojo.isFederate> \r\n				\"honor_labels\": ${jobPojo.honor_labels},\r\n				\"params\": {\r\n					\"match[]\": [\r\n						\"{__name__=~\\\".+\\\"}\"\r\n					]\r\n				},\r\n				\"authorization\":{\r\n					\"type\":\"Bearer\",\r\n					\"credentials\":\"${jobPojo.token}\"\r\n				},\r\n				</#if>\r\n				\"metrics_path\": <#if jobPojo.metrics_path?default(\"\")?trim?length gt 1>\r\n									\"${jobPojo.metrics_path}\",\r\n								<#else>\r\n									\"/metric\",\r\n								</#if>\r\n				\"static_configs\":[\r\n					<#list jobPojo.staticConfigList as staticConf >\r\n						{\r\n						  \"targets\": [\r\n								<#list staticConf.targets as targetConf>\r\n										\"${targetConf}\"<#sep>,</#sep>\r\n								</#list>\r\n							]\r\n						<#if staticConf.labels ??&& (staticConf.labels?size >0)>\r\n						   ,\r\n						   \"labels\": {\r\n								<#list staticConf.labels?keys as itemKey>\r\n									\"${itemKey}\":<#if staticConf.labels[itemKey]?default(\"\")?trim?length gt 1>\r\n													\"${staticConf.labels[itemKey]}\"\r\n												  <#else>\"\"</#if><#sep>,</#sep>\r\n								</#list>\r\n							} \r\n						</#if>\r\n						}<#sep>,</#sep>\r\n					</#list>\r\n					],\r\n				\"relabel_configs\": [\r\n					{\r\n						\"regex\": \"job\",\r\n						\"action\": \"labeldrop\"\r\n					}\r\n					<#if jobPojo.instanceRelabel> \r\n					,\r\n					{\r\n						\"regex\": \"instance\",\r\n						\"action\": \"labeldrop\"\r\n					}\r\n					</#if>\r\n				],\r\n				\"metric_relabel_configs\": [\r\n					{\r\n						\"regex\": \"instance\",\r\n						\"action\": \"labeldrop\"\r\n					}\r\n				]\r\n			}<#sep>,</#sep>\r\n		</#list>\r\n	]\r\n	</#if>\r\n}', 1, 'prometheus config文件模板');


DELETE from sys_config where param_key = "monitor_endpoint_export_header";
INSERT INTO `sys_config`(`id`, `param_key`, `param_value`, `status`, `remark`) VALUES (NULL, 'monitor_endpoint_export_header', '{\"cn\":{\"*系统\":\"系统名称(必填) \\n示例: Nezha\",\"*组件\":\"组件名称(必填) \\n示例: node_exporter\",\"名称\":\"实例名称 \\n示例: node_exporter\",\"资产名称\":\"资产名称(非必填) 与 主机地址 不能同时为空 \\n示例: A0420200101\",\"配置\":\"实例配置，JSON格式， \\n示例: {\\\"key\\\":\\\"value\\\"}\",\"启用\":\"启用状态（非必填） 可选 0:停用 1:启用,为空时默认为1 \\n示例: 1\"},\"en\":{\"*Project Name\":\"Project Name(Required) \\nExample: Nezha\",\"*Module Name\":\"Module Name(Required) \\nExample: node_exporter\",\"Name\":\"Endpoint name \\nExample: node_exporter\",\"Asset Name\":\"Asset name(Not required) And host address cannot be empty at the same time \\n示例: A0420200101\",\"Configs\":\"Endpoint Configs，JSON format， \\nExample: {\\\"key\\\":\\\"value\\\"}\",\"Enabled\":\"Enable state (not required) Optional values 0: Disable 1: Enable, when empty, the default is 1 \\nExample: 1\"}}', 1, 'monitor endpoint 导入表头');

ALTER TABLE `sys_log` 
ADD COLUMN `api_key_id` int(10) NULL DEFAULT NULL COMMENT '关联 sys_api_key.id' AFTER `create_date`;

DROP TABLE IF EXISTS `sys_api_key`;
CREATE TABLE `sys_api_key`  (
  `id` int(10) NOT NULL AUTO_INCREMENT COMMENT '主键',
  `name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '名称 唯一不重复',
  `token` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '密钥 唯一不重复',
  `role_id` int(10) NOT NULL COMMENT '角色id',
  `create_by` int(10) NOT NULL COMMENT '创建用户',
  `create_at` datetime(0) NOT NULL COMMENT '创建时间',
  `expire_at` datetime(0) NULL DEFAULT NULL COMMENT '失效时间 为空不失效',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 5 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = Dynamic;